"""Freeze with the target CPython compiler, never the host Python bytecode."""
import json
from pathlib import Path
import subprocess
import sys
import tempfile

tool, root, target = map(Path, sys.argv[1:])
modules = json.loads((root / 'frozen_modules.json').read_text(encoding='utf-8'))
parts = ['/* Generated by generate_frozen.py; see frozen_modules.json. */',
         '#include "Python.h"', '#include "pycore_import.h"']
bootstrap, stdlib = [], []
with tempfile.TemporaryDirectory(prefix='freeze-cpython-') as folder:
    for name, source in modules.items():
        header = Path(folder) / 'module.h'
        subprocess.run([str(tool.resolve()), name, str(root / 'src' / source),
                        str(header)], check=True)
        parts.append(header.read_text(encoding='utf-8'))
        symbol = '_Py_M__' + name.replace('.', '_')
        entry = f'{{"{name}", {symbol}, sizeof({symbol}), {int(name == "encodings")}}},'
        (bootstrap if name.startswith('_frozen_') or name == 'zipimport' else stdlib).append(entry)
for name, entries in [('bootstrap', bootstrap), ('stdlib', stdlib), ('tests', [])]:
    parts.append(f'static const struct _frozen {name}[] = {{\n' +
                 '\n'.join(entries) + '\n{0}\n};')
parts += ['const struct _frozen *_PyImport_FrozenBootstrap = bootstrap;',
          'const struct _frozen *_PyImport_FrozenStdlib = stdlib;',
          'const struct _frozen *_PyImport_FrozenTest = tests;',
          'const struct _frozen *PyImport_FrozenModules = NULL;',
          'static const struct _module_alias aliases[] = {',
          '{"_frozen_importlib", "importlib._bootstrap"},',
          '{"_frozen_importlib_external", "importlib._bootstrap_external"}, {0}};',
          'const struct _module_alias *_PyImport_FrozenAliases = aliases;']
target.parent.mkdir(parents=True, exist_ok=True)
target.write_text('\n'.join(parts) + '\n', encoding='utf-8')
